const DATA={"model": "gemini-3.5-flash-lite", "timestamp": "2026-10-15T23:25:38.373Z", "scope": "Gerçek sitelerden kısa kesit; tam sözleşme değil.", "cases": {"netflix": {"name": "Netflix", "source": "https://help.netflix.com/en/legal/termsofuse", "result": {"version": 1, "score": 15, "status": "complete", "risks": [{"category": "auto_renewal", "quote": "Your Netflix subscription will continue and automatically renew until terminated.", "explanation": "Üyeliğiniz iptal edilene kadar otomatik olarak yenilenmeye devam edecektir.", "confidence": 1, "start": 0, "end": 81}], "rejected": [], "uncertainties": [], "chunks": 1, "truncated": false, "disclaimer": "Hukuki tavsiye değildir. Bilgilendirme amaçlıdır; önemli kararlar için bir hukuk uzmanına danışın."}}, "spotify": {"name": "Spotify", "source": "https://www.spotify.com/de/legal/end-user-agreement/", "result": {"version": 1, "score": null, "status": "review", "risks": [], "rejected": [], "uncertainties": ["Sözleşmede otomatik yenileme, iptal ücreti, iade kısıtı, veri paylaşımı, içerik lisansı, tek taraflı değişiklik, tahkim ve sorumluluk sınırlaması ile ilgili bilgi bulunmamaktadır.", "Doğrulanmış bulgu çıkmadı. Bu, belgenin risksiz olduğunu göstermez."], "chunks": 1, "truncated": false, "disclaimer": "Hukuki tavsiye değildir. Bilgilendirme amaçlıdır; önemli kararlar için bir hukuk uzmanına danışın."}}}};

const labels={auto_renewal:'Otomatik yenileme',refund_limit:'İade sınırlaması',cancellation_fee:'İptal ücreti',content_license:'İçerik lisansı'};
const $=id=>document.getElementById(id);
function show(id){const c=DATA.cases[id],r=c.result;$('source').textContent=c.name+' · '+DATA.scope;$('meta').textContent='Model: '+DATA.model+' · Kayıt: '+DATA.timestamp;$('url').textContent=c.source;$('url').href=c.source;$('score').textContent=r.score===null?'—':r.score+'/100';$('verdict').textContent=r.status==='complete'?'Kanıtlı analiz tamamlandı':'İnsan incelemesi gerekli';$('risks').replaceChildren();for(const x of r.risks){const a=document.createElement('article'),h=document.createElement('h3'),q=document.createElement('blockquote'),p=document.createElement('p');h.textContent=labels[x.category]||x.category;q.textContent=x.quote;p.textContent=x.explanation;a.append(h,q,p);$('risks').append(a);}$('uncertainties').replaceChildren();for(const u of r.uncertainties){const p=document.createElement('p');p.textContent=u;$('uncertainties').append(p);}$('uncertainties').hidden=!r.uncertainties.length;$('score-note').textContent=r.score===null?'Bulgu çıkmaması, belgenin risksiz olduğu anlamına gelmez.':'Puan sabit kategori ağırlığıdır; hukuki geçersizlik veya zarar olasılığı değildir.';}
$('scenario').addEventListener('change',e=>show(e.target.value));show('netflix');
